def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    import datetime
    import pytz

    try:
        if not isinstance(nanoseconds, int):
            raise ValueError("nanoseconds must be an integer")

        if tz is None:
            tz = pytz.utc
        elif not isinstance(tz, datetime.tzinfo):
            raise ValueError("tz must be an instance of datetime.tzinfo")

        seconds = nanoseconds // 1_000_000_000
        nanos = nanoseconds % 1_000_000_000
        dt = datetime.datetime(1970, 1, 1, tzinfo=tz) + datetime.timedelta(seconds=seconds, microseconds=nanos // 1000)
        return dt.time()

    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise ValueError("Expected a timedelta instance")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, datetime.time):
        raise TypeError("Expected a datetime.time object")

    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance")

    return {
        "lat": value.lat,
        "lon": value.lon,
        "time": value.time.isoformat()
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        if hasattr(self, '_record') and self._record is not None:
            return list(self._record.keys())
        else:
            raise ValueError("Record is not properly initialized or is None")
    except AttributeError:
        raise AttributeError("Object does not have a _record attribute")
    except Exception as e:
        raise Exception(f"An error occurred while retrieving keys: {e}")

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError('Key not found: %s' % (key,))

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._items.values())

    result = []
    for key in keys:
        try:
            result.append(self._items[key])
        except KeyError:
            raise KeyError(f"Key '{key}' not found in the record.")
        except TypeError:
            raise TypeError(f"Index '{key}' is invalid. Please provide a valid key.")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(self._fields)

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._fields):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._field_names[key]] = self._fields[key]
        elif isinstance(key, str):
            result[key] = self._fields.get(self._field_names.index(key), None)
        else:
            raise TypeError("Keys must be integers or strings")

    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Insufficient data to pop a 16-bit integer")
    data = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(data, byteorder='big', signed=False)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f'Class name must be a valid identifier: {name!r}')

    if not isinstance(fields, (list, tuple)):
        raise TypeError(f'Fields must be a list or tuple: {fields!r}')

    if not isinstance(srid_map, dict):
        raise TypeError(f'SRID map must be a dictionary: {srid_map!r}')

    # Validate field names
    seen = set()
    for field in fields:
        if not isinstance(field, str) or not field.isidentifier():
            raise TypeError(f'Field names must be valid identifiers: {field!r}')
        if keyword.iskeyword(field):
            raise TypeError(f'Field names must not be keywords: {field!r}')
        if field in seen:
            raise TypeError(f'Field name duplicated: {field!r}')
        seen.add(field)

    # Define the new Point subclass
    namespace = {
        '__slots__': fields,
        '__init__': lambda self, *args: (setattr(self, field, arg) for field, arg in zip(fields, args)),
        '__repr__': lambda self: f"{name}({', '.join(f'{field}={getattr(self, field)!r}' for field in fields)})",
        'srid_map': srid_map
    }

    # Create the new class
    PointSubclass = types.new_class(name, bases=(object,), kwds=None, exec_body=lambda ns: ns.update(namespace))
    return PointSubclass

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        import warnings

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    try:
        # Split the version string by the dot separator
        parts = s.split('.')
        # Convert each part to an integer
        version_tuple = tuple(int(part) for part in parts)
        return version_tuple
    except ValueError:
        raise ValueError(f"Invalid version string '{s}'. Version string should contain only numbers separated by dots.")
    except AttributeError:
        raise TypeError(f"Expected a string, but got {type(s).__name__}.")

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    from collections.abc import MutableMapping
    from functools import wraps

    class MRUCache(MutableMapping):
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.order = []

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            self.move_to_end(key)
            return self.cache[key]

        def __setitem__(self, key, value):
            if key in self.cache:
                self.move_to_end(key)
            else:
                if len(self.cache) >= self.maxsize:
                    oldest_key = self.order.pop(0)
                    del self.cache[oldest_key]
            self.cache[key] = value
            self.order.append(key)

        def __delitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            self.order.remove(key)
            del self.cache[key]

        def __iter__(self):
            return reversed(self.order)

        def __len__(self):
            return len(self.cache)

        def move_to_end(self, key):
            self.order.remove(key)
            self.order.append(key)

        def clear(self):
            self.cache.clear()
            self.order.clear()

    def decorator(func):
        if maxsize is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        else:
            cache = MRUCache(maxsize, typed)

            def wrapper(*args, **kwargs):
                if typed:
                    key = (args, frozenset(kwargs.items()))
                else:
                    key = args + tuple(sorted(kwargs.items()))
                try:
                    return cache[key]
                except KeyError:
                    pass
                value = func(*args, **kwargs)
                cache[key] = value
                return value

        return wraps(func)(wrapper)

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    from functools import lru_cache as _functools_lru_cache

    def decorator(func):
        try:
            cached_func = _functools_lru_cache(maxsize=maxsize, typed=typed)(func)
        except TypeError:
            raise ValueError("Invalid arguments: maxsize must be an integer and typed must be a boolean")

        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return cached_func(*args, **kwargs)
            except Exception as e:
                raise RuntimeError(f"An error occurred while calling the cached function: {e}")

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Assuming self.data is an OrderedDict or similar structure
        key, value = self.data.popitem(last=False)
        return key, value
    except KeyError:
        raise KeyError('dict is empty')

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self._value:
            return self._value[key]
        else:
            self._value[key] = default
            return default
    except Exception as e:
        logger.error(f"setdefault: An error occurred - {e}")
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype: bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False

    try:
        return os.path.isfile(os.path.realpath(file_name))
