def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return object.__provides__
    except AttributeError:
        from zope.interface import implementedBy
        return implementedBy(object.__class__)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not all(isinstance(cls, type) for cls in classes):
        raise ValueError("All elements in the list must be classes (type).")

    # Use a set to track seen classes and avoid duplicates
    seen = set()
    minimal_classes = []

    for cls in reversed(classes):
        if cls not in seen:
            # Check if any subclass of cls is already in minimal_classes
            if not any(issubclass(m, cls) for m in minimal_classes):
                # Check if cls is a subclass of any class in minimal_classes
                if not any(issubclass(cls, m) for m in minimal_classes):
                    minimal_classes.append(cls)
                    seen.add(cls)

    # Reverse back to original order of first appearance
    minimal_classes.reverse()

    return minimal_classes

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    try:
        if not hasattr(self, '_interface'):
            raise AttributeError("Interface not defined")

        attributes = self._interface.__dict__.items()
        return {name: desc for name, desc in attributes if all or not name.startswith('_')}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        if all:
            return self.__dict__.keys()
        else:
            return [attr for attr in self.__dict__ if not attr.startswith('_')]
    except AttributeError:
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None or not hasattr(sequence, '__iter__'):
        raise ValueError("Argument `sequence` is not iterable")

    if hasattr(sequence, '__bases__') and 'Broken' in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if hasattr(zope.interface.InterfaceClass, '__mro__') and zope.interface.InterfaceClass in cls.__mro__ or hasattr(zope.interface.declarations.Implements, '__mro__') and zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except TypeError:
            raise ValueError("Elements of `sequence` must be iterable or interfaces")

    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        self.context = {}
        if hasattr(self, 'initial_value'):
            self.bins = [self.initial_value] * len(self.bins)
        else:
            self.bins = self.make_bins()
    except Exception as e:
        raise RuntimeError("Failed to reset histogram: {}".format(e))

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        coord = self.coords[coord_name]
        if hasattr(coord, 'attrs') and 'error_indices' in coord.attrs:
            return coord.attrs['error_indices']
        else:
            return []
    except (KeyError, AttributeError):
        return []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, (list, np.ndarray)) or not isinstance(edges, (list, np.ndarray)):
        raise ValueError("Both bins and edges must be lists or numpy arrays.")

    if len(bins) + 1 != len(edges):
        raise ValueError("The number of edges must be one more than the number of bins.")

    try:
        bins = np.array(bins)
        edges = np.array(edges)
    except Exception as e:
        raise ValueError("Failed to convert bins and edges to numpy arrays.") from e

    integral_value = 0.0
    for i in range(len(bins)):
        width = edges[i + 1] - edges[i]
        integral_value += bins[i] * width

    return integral_value

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest) and not isinstance(seq, Source):
        return True
    if isinstance(seq, (list, tuple)):
        return any(isinstance(item, FillRequest) and not isinstance(item, Source) for item in seq)
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        fill_method = getattr(obj, 'fill', None)
        request_method = getattr(obj, 'request', None)
        return callable(fill_method) and callable(request_method)
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except AttributeError:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif d1[key] != d2[key]:
            diff[key] = d1[key]
    return diff

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application is missing 'spec' or 'spec.manifest' attribute")

        default_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {"type": "string"},
                                    "status": {"type": "string"},
                                    "lastProbeTime": {"type": "string", "format": "date-time"},
                                    "lastTransitionTime": {"type": "string", "format": "date-time"},
                                    "reason": {"type": "string"},
                                    "message": {"type": "string"}
                                }
                            }
                        },
                        "readyReplicas": {"type": "integer"},
                        "replicas": {"type": "integer"}
                    }
                }
            }
        }

        for resource_name, resource in app.spec.manifest.items():
            if "observer_schema" not in resource:
                resource["observer_schema"] = default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
	) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of the
		in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*many_params* (:class:`~collections.abc.Iterable`) contains each set
		of in-style parameters (*params*).

		-	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
			contains the set of in-style parameters. It maps each parameter
			(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
			is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
			If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
			*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	A :class:`list` containing each set of converted out-style
			parameters (:class:`dict` or :class:`list`).
		"""
		from_style = self.SQLParams.in_style
		to_style = self.SQLParams.out_style

		if from_style == to_style:
			return sql, list(many_params)

		try:
			if from_style == 'qmark':
				param_format = '?'
			elif from_style == 'numeric':
				param_format = ':{}'
			elif from_style == 'named':
				param_format = ':{}'
			elif from_style == 'format':
				param_format = '{}'
			elif from_style == 'pyformat':
				param_format = '%({})s'
			else:
				raise ValueError(f"Unsupported in-style: {from_style}")

			if to_style == 'qmark':
				new_param_format = '?'
				param_counter = 1
			elif to_style == 'numeric':
				new_param_format = ':{}'
				param_counter = 1
			elif to_style == 'named':
				new_param_format = ':{}'
			elif to_style == 'format':
				new_param_format = '{}'
			elif to_style == 'pyformat':
				new_param_format = '%({})s'
			else:
				raise ValueError(f"Unsupported out-style: {to_style}")

			new_sql_parts = []
			new_many_params = []
			start = 0
			param_index = 0
			for match in self._param_regex[from_style].finditer(sql):
				new_sql_parts.append(sql[start:match.start()])
				param = match.group(0)
				if from_style == 'format':
					param_name = param_index
				elif from_style in ('qmark', 'numeric', 'pyformat'):
					param_name = param_counter
				else:
					param_name = param[1:] if from_style == 'named' else param[1:-1]

				if isinstance(next(iter(many_params[0])), Mapping):
					new_param_name = next(iter(many_params[0])) if to_style == 'format' else f'{param_name}'
				else:
					new_param_name = param_counter if to_style in ('qmark', 'numeric', 'pyformat') else f'{param_name}'

				new_sql_parts.append(new_param_format.format(new_param_name))
				start = match.end()
				if from_style in ('qmark', 'numeric', 'pyformat'):
					param_counter += 1
				param_index += 1

			new_sql_parts.append(sql[start:])
			new_sql = ''.join(new_sql_parts)

			for params in many_params:
				if isinstance(params, Mapping):
					new_params = {}
					for key, value in params.items():
						if to_style in ('qmark', 'numeric', 'pyformat'):
							new_params[param_counter] = value
							param_counter += 1
						else:
							new_params[key] = value
				else:
					new_params = list(params)
				new_many_params.append(new_params)

			return new_sql, new_many_params

		except Exception as e:
			raise ValueError(f"Error converting SQL parameters: {e}")

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = self.status  # Assuming 'status' is an attribute of the class
        return f"{prefix}{status}"
    except AttributeError:
        raise AttributeError("The 'status' attribute is missing from the instance.")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string.")
    try:
        log_entries = "\n".join(self.validation_log)
    except AttributeError:
        raise AttributeError("Object has no attribute 'validation_log'")
    return f"{prefix}{log_entries}"

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        spec_version = self.spec_version
        if extract_spec_version:
            type_value = inventory.get('type')
            if type_value == 'spec_version_1':
                spec_version = 1
            elif type_value == 'spec_version_2':
                spec_version = 2
            # Add more versions as needed
            # If no valid type or type not recognized, use default self.spec_version

        # Implement validation logic based on spec_version
        if spec_version == 1:
            self._validate_version_1(inventory)
        elif spec_version == 2:
            self._validate_version_2(inventory)
        else:
            raise ValueError(f"Unsupported specification version: {spec_version}")

    except Exception as e:
        raise ValueError(f"Validation failed: {str(e)}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, list) or not isinstance(digests_used, set):
        raise ValueError("manifest_files must be a list and digests_used must be a set")

    # Extract digests from manifest_files
    digests_needed = set()
    for mf in manifest_files:
        if not isinstance(mf, dict) or 'digest' not in mf:
            raise ValueError("Each element in manifest_files must be a dict with a 'digest' key")
        digests_needed.add(mf['digest'])

    # Check if all needed digests are present and used
    for digest in digests_needed:
        if digest not in digests_used:
            raise ValueError(f"Digest {digest} is present in manifest but not used")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The provided prior is not an instance of InventoryValidator")

    if self.inventory.keys() != prior.inventory.keys():
        raise ValueError("The keys in the current inventory do not match the keys in the prior inventory")

    for key in self.inventory:
        if not isinstance(self.inventory[key], dict) or not isinstance(prior.inventory[key], dict):
            raise ValueError(f"Inventory entry for {key} is not a dictionary in one or both inventories")

        if self.inventory[key].keys() != prior.inventory[key].keys():
            raise ValueError(f"The sub-keys in the current inventory entry for {key} do not match those in the prior inventory entry")

        for sub_key in self.inventory[key]:
            if self.inventory[key][sub_key].get('type') != prior.inventory[key][sub_key].get('type'):
                raise ValueError(f"The type for sub-key {sub_key} in inventory entry {key} does not match between current and prior inventories")

            if self.inventory[key][sub_key].get('required') != prior.inventory[key][sub_key].get('required'):
                raise ValueError(f"The required flag for sub-key {sub_key} in inventory entry {key} does not match between current and prior inventories")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not inventory or version not in inventory:
        raise ValueError("Invalid inventory or version provided.")

    path_map = {}

    for logical_path, file_details in inventory.get(version, {}).items():
        if isinstance(file_details, dict):
            content_files = file_details.get('content_files', set())
        elif isinstance(file_details, list):
            content_files = set(file_details)
        else:
            content_files = {file_details}

        path_map[logical_path] = content_files

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    for file_name, data in fixity.items():
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' in fixity block not found in manifest")

        if not isinstance(data, dict):
            raise ValueError(f"Fixity data for '{file_name}' must be a dictionary")

        if 'checksum' not in data:
            raise ValueError(f"Checksum missing for file '{file_name}' in fixity block")

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not os.path.exists(path):
        return []
    if os.path.isfile(path):
        return [path]
    if os.path.isdir(path):
        return [os.path.join(path, f) for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    return []

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str):
        raise ValueError("The folder parameter must be a string.")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The folder '{folder}' does not exist or is not a directory.")

    packages_data = {}

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    xml_data = ET.tostring(root_element, encoding='unicode')
                    base_name = os.path.splitext(file)[0]

                    if base_name not in packages_data:
                        packages_data[base_name] = []

                    packages_data[base_name].append((file, xml_data))

                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}. Skipping this file.")
                except Exception as e:
                    print(f"An error occurred while processing {file_path}: {e}")

    return packages_data

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
    """
    try:
        file_name = os.path.basename(file_path)
        file_folder = os.path.dirname(file_path)

        if file_name.startswith(prefix):
            if 'asset' in file_name:
                file_type = 'asset'
            elif 'rendition' in file_name:
                file_type = 'rendition'
            else:
                raise ValueError("Arquivo não identificado como 'asset' ou 'rendition'.")

            return {
                'type': file_type,
                'path': file_path
            }
        else:
            raise ValueError("O nome do arquivo não corresponde ao prefixo esperado.")
    except Exception as e:
        return {
            'error': str(e)
        }

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise ValueError("Input content must be a string")

    try:
        fixed_content = content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the content: {e}")

    return fixed_content

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if not node or not pubdate_xpaths:
        return None

    for xpath in pubdate_xpaths:
        try:
            match = node.xpath(xpath)
            if match:
                return match[0]
        except Exception as e:
            continue

    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    if debug:
        return f"{indent_str}<Debug: {self.__class__.__name__} at {hex(id(self))}>"
    else:
