def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, a, b = expr
            if op == '&':
                if isinstance(b, tuple) and b[0] == '|':
                    if a == b[1] or a == b[2]:
                        return a
                    if isinstance(b[1], tuple) and b[1][0] == '~' and b[1][1] == a:
                        return ('&', a, b[2])
                    if isinstance(b[2], tuple) and b[2][0] == '~' and b[2][1] == a:
                        return ('&', a, b[1])
            elif op == '|':
                if isinstance(b, tuple) and b[0] == '&':
                    if a == b[1] or a == b[2]:
                        return a
                    if isinstance(b[1], tuple) and b[1][0] == '~' and b[1][1] == a:
                        return ('|', a, b[2])
                    if isinstance(b[2], tuple) and b[2][0] == '~' and b[2][1] == a:
                        return ('|', a, b[1])
        return expr

    return [apply_absorption(arg) for arg in args]

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.
    """
    if not isinstance(user, str):
        raise ValueError("User must be a string.")
    if not isinstance(etcd_host, str):
        raise ValueError("ETCD host must be a string.")
    if not isinstance(etcd_port, int):
        raise ValueError("ETCD port must be an integer.")
    if etcd_port <= 0:
        raise ValueError("ETCD port must be a positive integer.")

    return {
        "user": user,
        "etcd_host": etcd_host,
        "etcd_port": etcd_port
    }

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def inner_func(*args, **kwargs):
        if sys.version_info[0] >= 3:
            return namefunc(*args, **kwargs)
        else:
            return [item.encode('utf-8') for item in namefunc(*args, **kwargs)]
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Attempt to load version information from version.py
        with open('version.py', 'r') as rfile:
            contents = rfile.read().strip()

        version_line = [line for line in contents.split('\n') if line.startswith('VERSION =')]
        if version_line:
            _, version = version_line[0].split('=')
            version = version.strip()
            return version.strip('"\'')

        # If VERSION is not found, return default
        return "default"

    except FileNotFoundError:
        # If version.py is not found, return default
        return "default"

    except Exception as e:
        # Handle any other exceptions and return default
        print(f"An error occurred: {e}")
        return "default"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list) or not all(isinstance(piece, str) for piece in pieces):
        raise ValueError("Pieces must be a list of strings.")
    if not isinstance(style, str):
        raise ValueError("Style must be a string.")

    try:
        if style == 'semver':
            return '.'.join(pieces)
        elif style == 'dash':
            return '-'.join(pieces)
        elif style == 'underscore':
            return '_'.join(pieces)
        else:
            raise ValueError(f"Unsupported style: {style}")
    except Exception as e:
        raise RuntimeError(f"Error rendering version: {e}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if not isinstance(vcs, str):
            raise ValueError("VCS must be a string.")
        if not isinstance(method, str):
            raise ValueError("Method must be a string.")
        if not callable(f):
            raise ValueError("The provided function is not callable.")

        if 'HANDLERS' not in globals():
            global HANDLERS
            HANDLERS = {}

        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        if method in HANDLERS[vcs]:
            raise ValueError(f"A handler for {vcs} with method {method} is already registered.")

        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        # Assuming self.hierarchy is the root of the hierarchy to validate
        queue = [self.hierarchy]

        while queue:
            current_node = queue.pop(0)
            num_objects += 1

            if validate_objects and not self._validate_object(current_node):
                if show_warnings:
                    print(f"Warning: Object {current_node} is invalid.")
                continue

            if check_digests and not self._check_digest(current_node):
                if show_warnings:
                    print(f"Warning: Digest mismatch for object {current_node}.")
                continue

            good_objects += 1

            # Assuming current_node.get_children() returns a list of child nodes
            queue.extend(current_node.get_children())

    except AttributeError:
        if show_warnings:
            print("Warning: Hierarchy is not properly structured or initialized.")
        return num_objects, good_objects

    except Exception as e:
        if show_warnings:
            print(f"An error occurred: {e}")
        return num_objects, good_objects

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    try:
        # Create the root directory if it doesn't exist
        if not os.path.exists(self.storage_root):
            os.makedirs(self.storage_root)

        # Create the required OCFL directory structure
        object_inventory_dir = os.path.join(self.storage_root, 'inventory')
        if not os.path.exists(object_inventory_dir):
            os.makedirs(object_inventory_dir)

        # Create the required OCFL files
        inventory_file_path = os.path.join(self.storage_root, 'inventory', 'inventory.json')
        if not os.path.exists(inventory_file_path):
            with open(inventory_file_path, 'w') as f:
                initial_inventory = {
                    "id": self.storage_root,
                    "type": "ocfl:storageRoot",
                    "digestAlgorithm": "sha512",
                    "created": datetime.now().strftime('%Y-%m-%dT%H:%M:%SZ'),
                    "storage": {
                        "objectRoots": []
                    }
                }
                json.dump(initial_inventory, f, indent=2)

        # Create the .ocfl_root file
        ocfl_root_file_path = os.path.join(self.storage_root, 'ocfl_1.0.txt')
        if not os.path.exists(ocfl_root_file_path):
            with open(ocfl_root_file_path, 'w') as f:
                f.write('1.0')

    except Exception as e:
        raise ValueError(f"Failed to initialize OCFL storage root: {e}")

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        parts = version.split('.')
        if len(parts) != 3:
            raise ValueError("Version must be in the format X.Y.Z")

        major, minor, patch = parts
        patch = str(int(patch) + 1)

        # Handle zero-prefixed versions
        if len(major) > 1 and major.startswith('0'):
            major = '0' + str(int(major[1:]))
        if len(minor) > 1 and minor.startswith('0'):
            minor = '0' + str(int(minor[1:]))
        if len(patch) > 1 and patch.startswith('0'):
            patch = '0' + str(int(patch[1:]))

        return f"{major}.{minor}.{patch}"

    except Exception as e:
        raise ValueError(f"Invalid version format: {version}") from e

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    if not version_dirs:
        return

    root_inventory = self.get_inventory(version_dirs[0])
    differing_digests = {}

    for version in version_dirs:
        try:
            inventory = self.get_inventory(version)
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found for version {version}.")
        except Exception as e:
            raise Exception(f"An error occurred while reading inventory for version {version}: {e}")

        for item, digest in inventory.items():
            if item in root_inventory and digest != root_inventory[item]:
                if version not in differing_digests:
                    differing_digests[version] = {}
                differing_digests[version][item] = digest

    return differing_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")

    if not isinstance(bug_ids, list) or not all(isinstance(bug_id, int) for bug_id in bug_ids):
        raise ValueError("bug_ids must be a list of integers")

    params['ids'] = ','.join(map(str, bug_ids))
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict
    from ruamel.yaml.nodes import MappingNode

    merged_nodes = defaultdict(lambda: None)

    for key_node, value_node in nodes:
        key = key_node.value

        if isinstance(value_node, MappingNode):
            if key not in merged_nodes or not isinstance(merged_nodes[key][1], MappingNode):
                merged_nodes[key] = (key_node, MappingNode(value_node.tag, [], start_mark=value_node.start_mark, end_mark=value_node.end_mark))
            for child_key_node, child_value_node in value_node.value:
                merged_nodes[key][1].value.append((child_key_node, child_value_node))
        else:
            merged_nodes[key] = (key_node, value_node)

    # Remove duplicates in MappingNode values
    for key in merged_nodes:
        if isinstance(merged_nodes[key][1], MappingNode):
            seen = set()
            unique_items = []
            for item in merged_nodes[key][1].value:
                item_key = item[0].value
                if item_key not in seen:
                    seen.add(item_key)
                    unique_items.append(item)
                else:
                    # Replace the existing item with the new one (last wins)
                    unique_items = [x for x in unique_items if x[0].value != item_key]
                    unique_items.append(item)
            merged_nodes[key][1].value = unique_items

    return list(merged_nodes.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

