                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge(mapping_nodes):
        merged_dict = {}
        for key_node, value_node in mapping_nodes:
            key = key_node.value
            if isinstance(value_node, MappingNode):
                if key in merged_dict:
                    merged_value = merge(merged_dict[key]['value'] + value_node.value)
                    merged_dict[key] = {'key_node': key_node, 'value': merged_value}
                else:
                    merged_dict[key] = {'key_node': key_node, 'value': value_node.value}
            else:
                merged_dict[key] = {'key_node': key_node, 'value': [value_node]}
        return [(item['key_node'], MappingNode(tag='tag:yaml.org,2002:map', value=item['value'])) if isinstance(item['value'], list) else (item['key_node'], item['value'][0]) for item in merged_dict.values()]

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, MappingNode):
            if key in merged:
                merged[key]['value'] += value_node.value
            else:
                merged[key] = {'key_node': key_node, 'value': value_node.value}
        else:
            merged[key] = {'key_node': key_node, 'value': [value_node]}

    result = []
    for item in merged.values():
        if isinstance(item['value'], list) and all(isinstance(v, MappingNode) for v in item['value']):
            merged_value = merge(item['value'])
            result.append((item['key_node'], MappingNode(tag='tag:yaml.org,2002:map', value=merged_value)))
        elif isinstance(item['value'], list):
            result.append((item['key_node'], item['value'][-1]))
        else:
            result.append((item['key_node'], item['value']))

    return result

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse

    parser = argparse.ArgumentParser(description="Process some integers.")
    parser.add_argument('integers', metavar='N', type=int, nargs='+',
                        help='an integer for the accumulator')
    parser.add_argument('--sum', dest='accumulate', action='store_const',
                        const=sum, default=max,
                        help='sum the integers (default: find the max)')

    try:
        if arguments:
            return parser.parse_args(arguments)
        else:
            return parser.parse_args()
    except argparse.ArgumentError as e:
        print(f'Argument Error: {e}')
        parser.print_help()
    except Exception as e:
        print(f'An error occurred: {e}')

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(sorted(flags))

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name', help='sub-command help')

    # Example subparser
    parser_a = subparsers.add_parser('a', help='A help')
    parser_a.add_argument('foo', type=int, help='foo help')

    parser_b = subparsers.add_parser('b', help='B help')
    parser_b.add_argument('bar', type=str, help='bar help')

    # Parse the arguments
    try:
        args, unknown = parser.parse_known_args(unparsed_arguments)
        result = {}
        if args.subparser_name:
            result[args.subparser_name] = args
        else:
            result["global"] = args
        return result
    except argparse.ArgumentError as e:
        print(f"Argument error: {e}")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements in the iterable must be dictionaries.")
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return url

    if not url_args or not isinstance(url_args, dict):
        return url

    for key, value in url_args.items():
        placeholder = f"{{{key}}}"
        if placeholder in url:
            url = url.replace(placeholder, str(value))

    return url

