def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("Alphabet must be a list with at least two elements.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer or None.")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    if not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise ValueError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise ValueError("register_value must be a string")

    try:
        for flow in flow_params.values():
            if isinstance(flow, dict):
                for key, value in list(flow.items()):
                    if key == register_value:
                        flow[register_number] = value
                        del flow[key]
                    elif isinstance(value, dict):
                        for sub_key, sub_value in list(value.items()):
                            if sub_key == register_value:
                                value[register_number] = sub_value
                                del value[sub_key]
    except Exception as e:
        raise RuntimeError(f"An error occurred while replacing register: {e}")

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("The value parameter must be a string.")
    if not isinstance(arg, str):
        raise ValueError("The arg parameter must be a string.")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for subcls in sc:
            if subcls not in seen:
                queue.add(subcls)

    seen.remove(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise ValueError("Input string must be of type str.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must be a list of strings.")
    if len(alphabet) < 2:
        raise ValueError("Alphabet must contain at least two unique characters.")

    base = len(alphabet)
    try:
        inverse_alphabet = {char: index for index, char in enumerate(alphabet)}
    except TypeError:
        raise ValueError("All elements in the alphabet must be hashable.")

    number = 0
    exp = len(string) - 1
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character '{char}' in string is not in the alphabet.")
        number += inverse_alphabet[char] * (base ** exp)
        exp -= 1

    return number

def unquote(name):
    """Remove quotes from the given name."""
    if isinstance(name, str):
        return re.sub(r'^["\']|["\']$', '', name)
    return name

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import subprocess
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive {archive_path} does not exist.")

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    tmp_path.mkdir(parents=True, exist_ok=True)

    if filename is None:
        filename = os.path.basename(archive_path)

    extract_path = tmp_path / os.path.splitext(filename)[0]
    extract_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(extract_path)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(extract_path)], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(extract_path)], check=True)
        else:
            raise ValueError(f"Unsupported archive type for file: {archive_path}")
    except subprocess.CalledProcessError as e:
        shutil.rmtree(extract_path, ignore_errors=True)
        raise RuntimeError(f"Failed to extract archive {archive_path}: {e}")

    return f"file://{extract_path.resolve()}"

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(["git", "check-ignore", "-v"] + ignored, stderr=subprocess.STDOUT, text=True)
        ignored_files = set()
        for line in output.splitlines():
            if line.split() and line.split()[3] in ignored:
                ignored_files.add(line.split()[3])
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        return "Error: " + e.output.strip()
    except Exception as e:
        return "An unexpected error occurred: " + str(e)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    import re
    match = re.match(r"^\s*(\d+)\s*([a-zA-Z]+)\s*$", frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number, unit = match.groups()
    number = int(number)
    unit = unit.lower().strip('s')  # Remove plural 's' if present

    try:
        if unit == "second" or unit == "sec":
            return datetime.timedelta(seconds=number)
        elif unit == "minute" or unit == "min":
            return datetime.timedelta(minutes=number)
        elif unit == "hour" or unit == "hr":
            return datetime.timedelta(hours=number)
        elif unit == "day":
            return datetime.timedelta(days=number)
        elif unit == "week":
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Cannot parse frequency: {frequency}") from e

def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: str or list of str, the script to convert.
    :param separator: str, the separator to use between commands.
    :return: str, the one line command.
    """
    if isinstance(script, str):
        script = script.splitlines()
    try:
        return separator.join(command.strip() for command in script if command.strip())
    except Exception as e:
        raise ValueError(f"Error converting script to one line: {e}")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("Invalid pattern type: %r" % (pattern,))
    if strip:
        pattern = pattern.strip()
    try:
        return re.compile(pattern)
    except re.error as e:
        raise ValueError("Invalid regex pattern: %r, error: %s" % (pattern, e))

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.STDOUT
        process = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            check=True,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True
        )

        return process.stdout

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed: {' '.join(full_command)}\nError: {e.stderr}")
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

