def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Legacy payload check
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "legacy_diaspora_field" in data:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Assuming Matrix requests have a specific header or parameter
        if isinstance(request, dict):
            return 'Authorization' in request and 'Bearer' in request.get('Authorization', '')
        elif hasattr(request, 'headers'):
            return 'Authorization' in request.headers and 'Bearer' in request.headers.get('Authorization', '')
        else:
            raise ValueError("Request object not supported")
    except Exception as e:
        print(f"Error identifying request: {e}")
        return False

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    # Regular expression to find URLs
    url_pattern = re.compile(r'(https?://[^\s]+)')

    def add_link_attributes(url):
        # Example attribute addition, can be customized
        return f'<a target="_blank" href="{url}">{url}</a>'

    def replace_with_links(m):
        url = m.group(0)
        return add_link_attributes(url)

    try:
        # Replace URLs in text with HTML links
        processed_text = url_pattern.sub(replace_with_links, text)
        return processed_text
    except Exception as e:
        # Handle any unexpected errors gracefully
        print(f"An error occurred: {e}")
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """
