def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise ValueError("Tag must be a string")
    if not tag:
        return False
    if not tag.isprintable():
        return False
    if len(tag) > 255:
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if not hasattr(node, 'getchildren'):
        raise ValueError("The provided node does not have 'getchildren' method.")

    result = {}
    for child in node.getchildren():
        if child.tag in result:
            if not isinstance(result[child.tag], list):
                result[child.tag] = [result[child.tag]]
            result[child.tag].append(child.text)
        else:
            result[child.tag] = child.text

    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("URL is required")

    if not document_path:
        document_path = "/.well-known/nodeinfo"

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": f"{url}{document_path}/2.0"
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse the document as JSON
        data = json.loads(document)
        if "links" in data:
            return {
                link.get("rel"): link.get("href")
                for link in data.get("links", [])
            }
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            if root.tag.endswith('}XRD'):
                return {
                    link.attrib['rel']: link.attrib['href']
                    for link in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')
                }
        except ET.ParseError:
            pass  # Parsing as XRD also failed

    # If both parsing methods fail, return an empty dictionary
    return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (IndexError, AttributeError):
        return None
    import urllib.request
    import urllib.error
    try:
        url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
        with urllib.request.urlopen(url) as response:
            return response.read().decode('utf-8')
    except (urllib.error.URLError, ValueError):
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
