def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    import yaml
    from jsonschema import validate, ValidationError

    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except Exception as e:
        raise IRValidatorException(f"There was a problem parsing the file: {str(e)}")

    # Define the required schema
    schema = {
        'type': 'object',
        'required': ['mandatory_field1', 'mandatory_field2'],  # Example mandatory fields
        'properties': {
            'mandatory_field1': {'type': 'string'},
            'mandatory_field2': {'type': 'integer'},
            # Add other fields and types as necessary
        }
    }

    try:
        validate(instance=data, schema=schema)
    except ValidationError as ve:
        raise IRValidatorException(f"Mandatory data is missing or invalid in the file: {ve.message}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    include_directive = 'include'
    if include_directive in parser_dict:
        includes = parser_dict.pop(include_directive)
        if not isinstance(includes, list):
            raise ValueError("The value of 'include' must be a list")

        for include in includes:
            if not isinstance(include, dict):
                raise ValueError("Each item in 'include' must be a dictionary")
            parser_dict.update(include)

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        defaults = {}
        for arg_name, arg_value in self._default_spec.items():
            defaults[arg_name] = arg_value
        for arg_name, arg_value in self.spec.items():
            defaults[arg_name] = arg_value
        return defaults
    except AttributeError as e:
        raise ValueError("Spec or default_spec is not properly set") from e

