def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict):
        raise ValueError("cli_args must be a dictionary")
    if not isinstance(answer_file_args, dict):
        raise ValueError("answer_file_args must be a dictionary")

    deprecated_arguments = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2'
    }  # Example deprecated arguments mapping

    for arg_mapping in [cli_args, answer_file_args]:
        for old, new in deprecated_arguments.items():
            if old in arg_mapping:
                print(f"Warning: The argument '{old}' has been deprecated in favor of '{new}'.")
                if new not in arg_mapping:
                    arg_mapping[new] = arg_mapping.pop(old)
                else:
                    print(f"Note: Both '{old}' and '{new}' are provided. Using '{new}'.")
                    arg_mapping.pop(old)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    command_options = {
        'main': [
            {'name': '--help', 'action': 'help', 'help': 'Show this help message and exit.'},
            {'name': '--version', 'action': 'version', 'version': '1.0.0', 'help': 'Show program\'s version number and exit.'}
        ],
        'virsh': [
            {'name': '--connect', 'help': 'Connect to the specified hypervisor.'},
            {'name': '--dry-run', 'action': 'store_true', 'help': 'Do everything but actually make the change.'}
        ],
        'ospd': [
            {'name': '--host', 'default': 'localhost', 'help': 'Host on which to listen.'},
            {'name': '--port', 'type': int, 'default': 8337, 'help': 'Port on which to listen.'}
        ]
    }

    try:
        return command_options[command_name]
    except KeyError:
        raise ValueError(f"No options found for command: {command_name}")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        if not isinstance(command_name, str) or not isinstance(argument_name, str):
            raise ValueError("Both command_name and argument_name must be strings.")

        command_spec = self.command_specs.get(command_name)
        if command_spec is None:
            raise KeyError(f"No specification found for command: {command_name}")

        argument_spec = command_spec.get(argument_name)
        if argument_spec is None:
            raise KeyError(f"No specification found for argument: {argument_name} in command: {command_name}")

        return argument_spec

    except (ValueError, KeyError) as e:
        print(f"Error: {e}")
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    if not isinstance(args, dict):
        raise ValueError("Expected args to be a dictionary")

    silenced_args = []
    for arg_name, arg_value in args.items():
        if arg_value in [None, '', False]:
            silenced_args.append(arg_name)
    return silenced_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, 'required_args'):
        raise AttributeError("The object must have a 'required_args' attribute defined.")

    if not isinstance(args, dict):
        raise ValueError("The 'args' parameter must be a dictionary.")

    missing_args = [arg for arg in self.required_args if arg not in args or args[arg] is None]

    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    for argn, argattrs in args.items():
        if not isinstance(argattrs, dict):
            raise ValueError(f"Attributes for argument '{argn}' must be a dictionary")
        value = argattrs.get('value')
        length = argattrs.get('length')

        if value is None:
            continue  # Skip if no value is provided

        if length is None:
            continue  # Skip if no length is specified

        if not isinstance(length, int) or length < 0:
            raise ValueError(f"Length for argument '{argn}' must be a non-negative integer")

        if isinstance(value, str):
            if len(value) > length:
                raise ValueError(f"The length of value for argument '{argn}' exceeds the specified length of {length}")
        else:
            raise ValueError(f"Value for argument '{argn}' must be a string")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        if hasattr(self, 'choices') and arg_name in self.choices:
            available_choices = self.choices[arg_name]
            if arg_value not in available_choices:
                raise ValueError(f"Invalid value for {arg_name}: {arg_value}. Available choices are {available_choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, (list, tuple)):
        raise TypeError("Arguments must be provided as a list or tuple.")

    for arg in args:
        if not isinstance(arg, dict) or 'value' not in arg or 'min' not in arg or 'max' not in arg:
            raise ValueError("Each argument must be a dictionary with 'value', 'min', and 'max' keys.")

        value = arg['value']
        min_value = arg['min']
        max_value = arg['max']

        if not isinstance(value, (int, float)) or not isinstance(min_value, (int, float)) or not isinstance(max_value, (int, float)):
            raise ValueError("Values for 'value', 'min', and 'max' must be numbers.")

        if value < min_value or value > max_value:
            raise ValueError(f"Value {value} is not between min {min_value} and max {max_value}.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    try:
        for key, value in args.items():
            if key.startswith('control_'):
                control_args[key] = value
            elif key.startswith('custom_'):
                custom_key = key[len('custom_'):]
                custom_args[custom_key] = value
            else:
                nested_args[key] = value
    except AttributeError:
        raise ValueError("Provided args should be a dictionary.")

    # If custom arguments are provided, they override nested arguments
    nested_args.update(custom_args)

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("Each element in extra_vars must be a dictionary")
        vars_dict.update(extra_var)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess

    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    command = ["ansible-playbook", playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        extra_vars_str = ' '.join([f"{k}={v}" for k, v in extra_vars.items()])
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for key, value in ansible_args.items():
            if value is None:
                command.append(f"--{key}")
            else:
                command.append(f"--{key}={value}")

    try:
        result = subprocess.run(command, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook execution failed with error: {e.stderr}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    parser = self.parsers.get(parser_name)
    if not parser:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg, value in values_dict.items():
        try:
            arg_type = next((action.type for action in parser._actions if action.dest == arg), None)
            if arg_type:
                values_dict[arg] = arg_type(value)
        except Exception as e:
            raise ValueError(f"Error converting argument '{arg}' to type {arg_type}: {e}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from collections import defaultdict

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        with open(spec_path, 'r') as file:
            plugin_spec = json.load(file)
        return flatten_dict(plugin_spec)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Error reading or parsing plugin spec file: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return path[len(root):].lstrip(os.sep)
